def add_info_to_maladie(apps, schema_editor):
    Maladie = apps.get_model("sa", "Maladie")
    Typage = apps.get_model("sa", "Typage")

    Maladie.objects.filter(name__in=ESPECE_LEVEL_2).update(intitule_typage_niveau_2="Espèce")
    Maladie.objects.filter(name__in=GENOTYPE_LEVEL_2).update(intitule_typage_niveau_2="Génotype")
    Maladie.objects.filter(name__in=SEROTYPE_LEVEL_2).update(intitule_typage_niveau_2="Sérotype")
    Maladie.objects.filter(name__in=SOUS_TYPE_LEVEL_2).update(intitule_typage_niveau_2="Sous-type")
    Maladie.objects.filter(name__in=TYPE_LEVEL_2).update(intitule_typage_niveau_2="Type")
    Maladie.objects.filter(name="Tremblante").update(
        intitule_typage_niveau_2="Forme", intitule_typage_niveau_3="Génotype"
    )
    Maladie.objects.filter(name="Diarrhée épizootique porcine").update(intitule_typage_niveau_2="Virulence")
    Maladie.objects.filter(name="Brucellose").update(intitule_typage_niveau_3="Biovar")
    Maladie.objects.filter(name="Tuberculose").update(intitule_typage_niveau_3="Spoligotype")
    Maladie.objects.filter(name="Encéphalopathie spongiforme bovine").update(intitule_typage_niveau_3="Sous-type")

    Maladie.objects.filter(name__in=MALADIE_AUTRE).update(intitule_typage_champ_libre="Autre spoligotype")
    Maladie.objects.filter(name__in=EMERGING).update(intitule_typage_champ_libre="Émergent")
    Maladie.objects.filter(name="Salmonellose (Salmonella)").update(intitule_typage_champ_libre="Sérotype")
    Maladie.objects.filter(intitule_typage_champ_libre="").update(intitule_typage_champ_libre="Typage complémentaire")
    for data in TUPLES_VALUES:
        maladie = Maladie.objects.get(name=data[0])
        Typage.objects.create(maladie=maladie, valeur_niveau_2=data[1], valeur_niveau_3=data[2] or "")


